using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // 1. Discriminator renamed from "Discriminator" to "$type" in EF Core 9.
        //    Preserve old name so existing documents and raw SQL queries still work.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // 2. id property no longer contains discriminator prefix in EF Core 9.
        //    Preserve old "Blog|1" format so existing documents remain accessible.
        modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

        // 3. HasIndex now throws for Cosmos entities (was silently ignored).
        //    Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
        //    Manage indexing via Azure Portal / Bicep / Terraform instead.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

